int given 7891;
int ans = 0;
int temp = given;
int num_digits = 0;
int place = 1;
while(temp>0){
num_digits++;
place = place*10
temp = temp/(place);
}
int mul = place;
int pos = 10;
while(given>0){
int digit = given%pos - (given%(pos/10));
ans += mul*digit;
mul = mul/10;
given = given/pos;
pos = pos*10;
}
return ans;
